#include <stdio.h>
#include <string.h>
#include <stdbool.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);
    if (plen >= 65 || tlen >= 65) {
        puts("USAGE");
        return 0;
    }
    bool dp[65][65] = {0};
    dp[0][0] = true;
    // Initialize first column (matching empty text)
    for (size_t i = 1; i <= plen; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }
    // Fill the DP table
    for (size_t i = 1; i <= plen; ++i) {
        for (size_t j = 1; j <= tlen; ++j) {
            if (pattern[i - 1] == '*') {
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pattern[i - 1] == '?' || pattern[i - 1] == text[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = false;
            }
        }
    }
    puts(dp[plen][tlen] ? "MATCH" : "NO_MATCH");
    return 0;
}
